            ## 玛娜
            - 大气中的无色超自然能量,注入属性后变质成元素魔法
            - 来源于世界核心'欧德·拉格纳',在大气&门&欧德之间循环流动
            - 所有生物体内天然含有玛娜,释放时会携带释放者的情绪
