            - 每个人拥有独一无二的魔纹(类似指纹的魔力特征),若两个存在共享同一魔纹则可互相借用玛娜
            
            ## 瘴气
            - 被魔女因子污染的玛娜,由拥有魔女力量的存在散发
            - 少量吸入不会立即生效,但大量吸入会严重影响精神,使人变得偏执&嗜杀
            - 最严重时会在数十秒内驱使人自残致死,对人类&亚人&人造精灵&地龙均有效
            - 瘴气甚至能污染食物并导致植物枯死
            - 贤者候选人据说对魔女散发的瘴气免疫
            
            ## 门
            - 每个生物体内的魔力通道,控制玛娜的吸收&释放
            - 门的大小与开放度因人而异,决定魔法潜力上限
            - 过度使用会损坏门,需专业治疗师修复,修复期间禁止使用魔法否则门将永久损坏
            - 门永久损坏者不仅无法施法,连从体内排出玛娜都做不到,称为'门缺陷'
            - 精灵可充当'伪门'替代损坏的门,帮助排出多余玛娜
            
            ## 欧德
            - 出生时便固定的生命力量容器,等同灵魂,储存玛娜并反映寿命
            - 紧急时可代替玛娜施法但会直接消耗寿命
            - 欧德耗尽后人不会死亡,但将不再是原来的自己
            
            ## 欧德·拉格纳
            - 世界之心,玛娜源泉,记忆回廊所在地
            
            # 六大元素
            
            ## 元素分类
            - 每类对应专属咒语和效果,个人兼容性决定可使用类型
            - 绝大多数人仅能兼容其中一种,兼容多种者并不罕见但仍属少数
            - 火(咒语: 戈亚Goa): 掌管温度变化,可操纵热量&火焰,也可通过降低空气中水分的温度来制造冰
            - 水(咒语: 冰Huma/水Shiha): 掌管生命力干涉与治愈,可创造新的水并将其塑形为冰; 水属性制造的冰用途结束后会消散回玛娜,火属性制造的冰则会留存
            - 风(咒语: 芙拉Fula): 作用于生物体外部,干涉大气,制造风刃&气流操控
            - 土(咒语: 德纳Dona): 作用于生物体内部,借大地之力可建造土壁防御&制造土弹攻击,也可用于肥沃或荒废土地
            - 阴(咒语: 夏玛Shamak): 掌管黑暗&分离等抽象概念,可操控时间&空间&感知隔离&重力; 阴阳两属性相互冲突,精通一方会影响另一方的习得
            - 阳(咒语: 籍瓦尔德Jiwald): 掌管光明&强化等抽象概念,可发射光束&增强身体性能; 阳魔法的增强效果极不稳定,受施术者精神状态&玛娜用量等多种因素影响,被增强者如同操控他人的身体般不协调,因此被视为忌讳之术鲜少使用; 但若运用得当可增强抗伤能力并放大使用者自身的特殊能力
            - 阴阳两属性的研究与开发均远落后于四大元素,阴属性尤其稀少
            
            ## 吟唱前缀
            - 吟唱可辅助凝聚力量,无前缀为基础级
            - El: 第二级,扩大范围与威力
            - Ul: 第三级,显著增强
            - Al: 最高级,毁灭性威力
            - 物理系魔法(如Huma)随前缀提升主要表现为体积与数量的增大
            - 概念系魔法(如Shamak)随前缀提升则表现为效果层次的深化: 从遮蔽视觉到剥离身体感知,最终将目标从世界中移除
            
            ## 施法条件
            - 门必须处于开启状态
            - 需要在心中构建效果图像才能施法成功
            - 精神状态影响魔法效果,尤其是阳魔法
            - 不习惯施法或消耗玛娜的人即使门容量大也会很快感到身心疲劳
            
            # 治愈魔法
            - 水魔法最核心的应用,几乎所有水属性使用者都会训练
            - 通过刺激目标的自然治愈力来加速伤口愈合与疾病治疗,效果可在瞬间发生
            - 熟练者可干涉身体机能: 麻痹痛觉(充当麻醉)&破坏魔力循环(瘫痪目标)
            - 治愈能力完全取决于使用者的天赋&技巧&魔力量
            - 核心限制: 无法复活死者; 无法治愈精神疾病&诅咒&权能造成的变形&死神加护造成的伤口; 似乎无法补充失去的血液
            
            # 精灵术
            - 与魔法师(通过自身门释放玛娜)不同,精灵术师借助精灵直接处理大气中的玛娜来施法
            - 精灵可充当契约者的伪门,为门损坏者提供施法途径
            - 优势: 多元素同时施法时各精灵分担对应元素,术师仅需指挥协调; 魔法师要做到同样的事必须承受类似同时使用多个大脑的负担
            - 劣势: 必须先与精灵缔结契约,需要辉石作为精灵的寄宿媒介,且可能无法随时召唤精灵
            - 目前大多数精灵术师集中在古斯提科圣王国
            
            # 高等技巧
            
            ## 多重施法
            - 同时施放多个独立法术,难度如同同时使用多个大脑
            - 当世仅罗兹瓦尔(最多六重)与艾佐·卡德纳(二重)能做到
            
            ## 伪装吟唱
            - 熟练魔法师可用不同的咒语名替代实际施放的法术,制造误判
            - 也可扩展或压缩法术外观: 将Al Goa压缩成蜡烛大小的火苗引诱敌人触碰,或将普通Goa膨胀成Al Goa的外观恐吓对手
            
            ## 魔法构成改写
            - 通过物理接触正在施放中的法术或他人的法术,可改写其魔法构成
            - 可将法术分解为玛娜并通过自身门吸收
            
            # 元素组合魔法
            - 同时操控多种元素进行施法,难度极高,精灵术师有天然优势
            - 已知组合: 双元素(Nect共享思想,光学迷彩); 三元素(飞行魔法); 四元素(闪电魔法,速度超越莱因哈鲁特); 六元素(全元素屏障)
            - 天候操控: 需要多种元素配合高品质辉石
            
            # 魔法媒介&资源
            
            ## 拉格麦特(魔石)
            - 自然生成的矿石,与特定元素关联,日常生活广泛使用
            - 通常不稳定需小心处理,火属性魔石受到足够震动或加热后会爆炸,常被当作炸药使用
            - 拥有门的人无论能否使用魔法都可以使用魔石
            
            ## 辉石
            - 稀有的无色小型拉格麦特,主要用作精灵术师的精灵寄宿媒介
            - 高品质辉石蕴含巨大能量可驱动强力法术,但代价是辉石本身会碎裂
            - 某些特殊辉石甚至可容纳大精灵或亡灵的灵魂
            
            ## 魔晶
            - 魔石的最纯净形态,由大量无色玛娜凝缩而成,极为稀有
            - 可通过收集&杀死精灵来人工制造
            - 大量魔晶聚集等同于巨型炸弹,需要魔力核心来稳定; 核心过载后的爆炸足以抹平至少一座帝都规模的区域
            
            ## 退魔水晶
            - 将玛娜还原为无色休眠状态,中和或削弱范围内的魔法效果
            
            ## 流星&魔造具
            - 流星: 强欲魔女艾姬多娜制造的特殊道具,拥有门的人均可使用,效果各异
            - 魔造具: 罗兹瓦尔·K·梅瑟斯推动生产的魔法工具,以魔石为动力源,科斯图尔工业都市是主要产地
            - 两者都不要求使用者本身能施法,只需拥有门即可驱动
            
            # 禁术
            
            ## Al Shario
            - 从天空降下燃烧的玛娜星体,每颗蕴含的玛娜量匹敌大精灵
            - 威力超越龙息,可轻松杀死多头龙
            
            ## Ol Shamak
            - 反魔女因子咒文,固定目标并停止门活动
            - 对魔女因子持有者效果最强,将其完全封入黑球
            - 使用特殊"Ol"前缀,与常规前缀体系独立,不代表强度而代表特殊分类
            - 由艾姬多娜创造
            
            ## 不死王的秘迹
            - 水魔法极致,复活尸体作为士兵,需要极高天赋
            - 原版无法召回灵魂,尸体保留生前技能但弱于生前
            - 斯芬克斯改良版可创造保留全部生前实力且能再生的尸兵
            - 复活时以能力巅峰状态呈现: 晚年死去者可能以青年时期的身体被复活
            
            # 失传魔法
            
            ## 灵魂转写
            - 将灵魂转移到血亲身体实现永生,艾姬多娜改良版可绕过血缘限制
            - 罗兹瓦尔使用此术存活400年
            
            ## 梦术
            - 探索并操控他人梦境的禁术,使用者被认为已灭绝
            - 精通者可创造容纳灵魂的梦之城堡&生成幻影分身&窥探记忆&植入思想
            - 某些梦术师被认为具有成为魔女的潜质
            
            ## 传送魔法
            - 阴属性操控空间实现瞬间移动,被视为高难度魔法
            - 已知实现方式: 预先在两地设置术式形成门户; 以消耗自身门为代价单向传送
            
            # 负面状态
            - 玛娜中毒: 吸收过量玛娜无法排出导致欧德崩溃,门缺陷者尤其易发; 可通过与精灵缔结契约排出多余玛娜来缓解
