            ## 相容性与代价
            - 相容者可无代价行使权能; 不相容者需以"对世界施加影响的可能性"作为补偿
            - 相容条件不明,似乎与对应之罪有某种关联
            
            ## 使徒
            - 权能持有者可分享部分因子给他人使其成为使徒,但会降低自身权能效力
            - 除暴食外因子不可分裂; 暴食是唯一可在多人间分裂并共享同一权能的特例
            
            ## 超员因子
            - 虚饰&忧郁是七大罪之外的超员因子,各自被量身定做给特定个体(勇者&圣女)
            - 其他人可使用但永远无法相容,必须支付代价
            
            ## 无因子权能
            - 因子相当于打开权能之门的钥匙,门一旦打开即使失去钥匙权能仍保留
            - 与因子相容者有深厚联系的人可能天生半开着通向权能的门
            
            ## 七大罪权能
            
            ### 怠惰
