            - 裴特鲁吉乌斯: 不可视之手,指头全在时最多七只,因子全回收后百只以上; 可附身精灵适性者
            - 菜月昴: Invisible Providence,单只不可视之手,射程与威力远逊前任; 集中精神可穿透物质
            
            ### 强欲
            - 艾姬多娜: 可观测过去&现在&未来的任何事件; 睿智之书是不完美复制品
            - 雷古勒斯: 狮子的心脏(停止自身时间达到无敌,上限5秒) + 小小的王(将心脏分享给妻子们绕过时限)
            - 菜月昴: Cor Leonis,小小的王的逆向形态,将他人负担转移至自身以增强对方; 可感知有情感联系者的位置与情绪
            
            ### 暴食
            - 达芙妮: 通过触碰或目光使人陷入极度饥饿
            - 莱伊&罗伊&路易(三人共享): 暴食(左手触碰后舔掌心吞噬名字&记忆; 名字被吃者存在从世界消失; 记忆被吃者失忆重置; 两者皆被吃者成为空壳) + 月食(运用受害者记忆收割技能,可组合但无法全力发挥,无法获得加护&权能) + 日食(变形为受害者外貌获得完整实力但失去其他能力)
            - 暴食因子天生具有创造生命&操控魔兽的特性
            
            ### 愤怒
            - 密涅瓦: 从世界灵魂汲取玛娜强制改写因果进行治愈,副作用在随机地点引发自然灾害
            - 西里乌斯: 洗魂,将极化情绪传递给周围所有人; 可共享痛苦与死亡,范围内一人死亡可迫使他人同死
            
            ### 色欲
            - 卡蜜拉: 无貌之花嫁,使人沉迷注视她而无法察觉自身受伤; 可令人将她看作最想见的人
