            ### 傲慢
            - 提丰: 以自身标准判定善恶,心怀愧疚者身体被粉碎; 对缺乏罪恶感能力的存在无效
            - 斯特莱德: 傲慢十戒,十枚戒指诅咒目标使其服从; 各色戒指有不同副效果
